def svg_capas():
    tr = {"Corteza": "Crust", "Delgada y sólida. Es la que se rompe en placas.": "Thin and solid. It is what breaks into plates.", "Manto": "Mantle",
          "La capa más gruesa. Roca caliente que fluye": "The thickest layer. Hot rock that flows", "muy despacio: centímetros por año.": "very slowly: inches per year.",
          "Núcleo externo": "Outer core", "Metálico y líquido.": "Metal and liquid.", "Núcleo interno": "Inner core",
          "Sólido pese al calor: la presión es tan alta": "Solid despite the heat: the pressure is so high", "que impide que fluya.": "that it cannot flow.",
          "Las flechas son corrientes de convección en el manto": "The arrows are convection currents in the mantle"}
    return C.svg_orig("7-1_0", tr, "Cutaway of Earth’s interior with its layers and the convection currents in the mantle. From the outside in: the crust, a thin solid layer we live on; the mantle, the thickest layer, made of hot rock that flows very slowly; the outer core, liquid metal; and the inner core, solid despite its very high temperature because of the enormous pressure on it. Looping convection currents are drawn in the mantle: hot material rises, cools as it nears the crust, moves sideways, and sinks again. Those currents are the engine that drags the plates of the crust.")


def svg_limites():
    tr = {"Divergente": "Divergent", "Se separan: sube material": "They pull apart: material rises", "Se crea corteza nueva": "New crust forms",
          "Convergente": "Convergent", "Chocan: la más densa se hunde": "They collide: the denser one sinks", "Volcanes, fosas y cordilleras": "Volcanoes, trenches, and mountains",
          "Transformante": "Transform", "Se deslizan de lado": "They slide past each other", "Terremotos, sin crear ni destruir": "Earthquakes, crust not made or destroyed",
          "En el límite convergente decide la densidad: se hunde la placa más densa": "At a convergent boundary density decides: the denser plate sinks"}
    return C.svg_orig("7-1_1", tr, "The three kinds of boundary between tectonic plates. At a divergent boundary, the two plates pull apart and material from the mantle rises through the gap and forms new crust, as at mid-ocean ridges. At a convergent boundary, the two plates collide: the denser one sinks under the other in a process called subduction, and volcanoes, ocean trenches, and large mountain ranges form there. At a transform boundary, the plates slide past each other sideways without making or destroying crust, and the stored-up friction is released as earthquakes.")


def svg_estratos():
    tr = {f"Capa {x}": f"Layer {x}" for x in "ABCDE"}
    tr.update({"Intrusión": "Intrusion", "Más reciente": "Youngest", "Más antigua": "Oldest", "Principio de superposición:": "Principle of superposition:",
               "lo de abajo se depositó primero.": "the bottom was laid down first.", "La intrusión corta A, B y C,": "The intrusion cuts A, B, and C,",
               "pero no D ni E: es posterior a C": "but not D or E: it is younger than C", "y anterior a D.": "and older than D.",
               "Lo que corta a una capa es siempre más joven que la capa que corta": "Whatever cuts across a layer is always younger than that layer"})
    return C.svg_orig("7-1_2", tr, "Rock column with five layers of sedimentary rock and an intrusion. From top to bottom are layer E, layer D, layer C, layer B, and layer A. By the principle of superposition, layer A, at the bottom, is the oldest, and layer E, at the top, is the youngest. An intrusion of igneous rock cuts through layers A, B, and C but not D or E, which shows that it formed after layer C was laid down and before layer D was.")


def columna(capas, corta, ancho=360, alto=230, falla=None):
    """SVG de una columna de capas (capas: de abajo arriba) con una intrusión que corta las 'corta' capas de abajo; falla opcional (n capas cortadas)."""
    n = len(capas); h = (alto - 30) / n; x0 = 20; w = 220
    col = ["#b39ddb", "#c5b3e6", "#d6c9ef", "#e4dbf6", "#efe9fa", "#f6f2fd"]
    out = [f'<svg viewBox="0 0 {ancho} {alto}" style="width:100%;max-width:{ancho}px;height:auto" role="img" aria-label="{{ARIA}}" xmlns="http://www.w3.org/2000/svg">']
    for i, c in enumerate(capas):
        y = 10 + (n - 1 - i) * h
        out.append(f'<rect x="{x0}" y="{y:.1f}" width="{w}" height="{h:.1f}" fill="{col[i % 6]}" stroke="#3c1478" stroke-width="1.5"/>')
        out.append(f'<text x="{x0 + 12}" y="{y + h / 2 + 5:.1f}" font-family="Segoe UI, sans-serif" font-size="14" font-weight="700" fill="#3c1478">{c}</text>')
    if corta:
        ytop = 10 + (n - corta) * h; ybot = 10 + n * h
        out.append(f'<polygon points="{x0 + 150},{ybot:.1f} {x0 + 172},{ybot:.1f} {x0 + 165},{ytop:.1f} {x0 + 157},{ytop:.1f}" fill="#5b21b6"/>')
        out.append(f'<text x="{x0 + 161}" y="{ybot + 16:.1f}" font-family="Segoe UI, sans-serif" font-size="11" font-weight="700" fill="#3c1478" text-anchor="middle">{t("Intrusion", "Intrusión")}</text>')
    if falla:
        ytop = 10 + (n - falla) * h; ybot = 10 + n * h
        out.append(f'<line x1="{x0 + 70}" y1="{ybot:.1f}" x2="{x0 + 110}" y2="{ytop:.1f}" stroke="#b3261e" stroke-width="3" stroke-dasharray="7 4"/>')
        out.append(f'<text x="{x0 + 112}" y="{ytop - 4:.1f}" font-family="Segoe UI, sans-serif" font-size="11" font-weight="700" fill="#b3261e">{t("Fault", "Falla")}</text>')
    out.append(f'<line x1="{x0 + w + 30}" y1="14" x2="{x0 + w + 30}" y2="{alto - 26}" stroke="#3c1478" stroke-width="2"/>')
    out.append(f'<polygon points="{x0 + w + 24},{alto - 32} {x0 + w + 30},{alto - 18} {x0 + w + 36},{alto - 32}" fill="#3c1478"/>')
    out.append(f'<text x="{x0 + w + 42}" y="22" font-family="Segoe UI, sans-serif" font-size="11" fill="#222">{t("Younger", "Más reciente")}</text>')
    out.append(f'<text x="{x0 + w + 42}" y="{alto - 22}" font-family="Segoe UI, sans-serif" font-size="11" fill="#222">{t("Older", "Más antigua")}</text>')
    out.append("</svg>")
    arriba = ", ".join(reversed(capas))
    aria = t(f"Rock column. From top to bottom: {arriba}.", f"Columna de capas. De arriba abajo: {arriba}.")
    if corta:
        aria += " " + t(f"An igneous intrusion cuts through the bottom {corta} layers: {', '.join(capas[:corta])}.", f"Una intrusión ígnea atraviesa las {corta} capas de abajo: {', '.join(capas[:corta])}.")
    if falla:
        aria += " " + t(f"A fault breaks the bottom {falla} layers: {', '.join(capas[:falla])}.", f"Una falla rompe las {falla} capas de abajo: {', '.join(capas[:falla])}.")
    return "".join(out).replace("{ARIA}", aria)


