        (t("Superposition", "Superposición"), t("In undisturbed layers, lower layers are older.", "En capas no alteradas, las de abajo son más antiguas.")),
        (t("Index fossil", "Fósil guía"), t("A fossil from a short-lived, widespread species, used to match layers of the same age.", "Fósil de una especie breve y extendida, que sirve para correlacionar capas de la misma edad.")),
