# ---------------------------------------------------------------- práctica
def banco_placas():
    O = [t("Divergent", "Divergente"), t("Convergent", "Convergente"), t("Transform", "Transformante")]
    d = [(t("Two plates pull apart and magma rises to fill the gap.", "Dos placas se separan y sube magma a rellenar la abertura."), 0, t("Pulling apart, new crust.", "Separación, corteza nueva.")),
         (t("An ocean plate sinks under a continent, and a chain of volcanoes forms.", "Una placa oceánica se hunde bajo un continente y se forma una cadena de volcanes."), 1, t("Subduction: convergent.", "Subducción: convergente.")),
         (t("Plates grind past each other sideways; there are many earthquakes but no volcanoes.", "Las placas rozan de lado; hay muchos terremotos, pero ningún volcán."), 2, t("Sideways, no magma.", "De lado, sin magma.")),
         (t("Two continents collide and the Himalaya Mountains are pushed up.", "Dos continentes chocan y se levanta el Himalaya."), 1, t("Collision builds mountains.", "El choque levanta cordilleras.")),
         (t("A ridge in the middle of the Atlantic makes new ocean floor.", "Una dorsal en medio del Atlántico crea fondo oceánico nuevo."), 0, t("Mid-ocean ridge: divergent.", "Dorsal oceánica: divergente.")),
         (t("California’s San Andreas Fault.", "La falla de San Andrés, en California."), 2, t("The classic transform boundary.", "El límite transformante clásico.")),
         (t("A deep ocean trench forms next to a coast.", "Se forma una fosa oceánica profunda junto a una costa."), 1, t("Trenches mark subduction.", "Las fosas marcan la subducción.")),
         (t("Iceland is slowly being split in two by rising magma.", "Islandia se va partiendo en dos por el magma que asciende."), 0, t("Rising magma between plates moving apart.", "Magma que sube entre placas que se separan."))]
    out = [{"enun": t("What kind of plate boundary is it?", "¿Qué tipo de límite de placa es?") + f"<br><strong>{x}</strong>", "ops": O, "ok": k, "enOrden": True,
            "pista": t("Is there magma? Rising between plates → divergent; with sinking and volcanoes → convergent; none, only earthquakes → transform.", "¿Hay magma? Sube entre placas que se separan → divergente; hay hundimiento y volcanes → convergente; no hay, solo sismos → transformante."), "exp": f"<strong>{O[k]}.</strong> {e}"} for x, k, e in d]
    capas = [(t("Which layer is liquid metal?", "¿Qué capa es metal líquido?"), [t("Outer core", "Núcleo externo"), t("Inner core", "Núcleo interno"), t("Mantle", "Manto")], 0, t("The inner core is solid because of the pressure.", "El interno es sólido por la presión.")),
             (t("Which layer breaks into plates?", "¿Qué capa se rompe en placas?"), [t("Crust", "Corteza"), t("Mantle", "Manto"), t("Outer core", "Núcleo externo")], 0, t("The thin, solid crust.", "La corteza, delgada y sólida.")),
             (t("How do we know about Earth’s inner layers?", "¿Cómo se conocen las capas internas de la Tierra?"), [t("From how earthquake waves travel through the inside", "Por cómo viajan por dentro las ondas de los terremotos"), t("From holes drilled to the center", "Por perforaciones hasta el centro"), t("From photographs", "Por fotografías")], 0, t("No one has drilled past the crust.", "Nadie ha perforado más allá de la corteza.")),
             (t("Which evidence for drifting continents is the weakest on its own?", "¿Qué evidencia de la deriva continental es la más débil por sí sola?"), [t("The coasts fit like puzzle pieces", "Las costas encajan como un rompecabezas"), t("The same land fossils on both sides of an ocean", "Los mismos fósiles terrestres a ambos lados del océano"), t("Earthquakes lined up in narrow belts", "Sismos alineados en franjas estrechas")], 0, t("A fit could be chance.", "Un encaje podría ser casualidad."))]
    for q, o, k, e in capas:
        out.append({"enun": f"<p>{q}</p>", "ops": o, "ok": k, "pista": t("Crust thin and solid; mantle thick, flows slowly; outer core liquid; inner core solid.", "Corteza delgada y sólida; manto grueso, fluye despacio; núcleo externo líquido; interno sólido."), "exp": e})
    return out


def clasif_rocas():
    G = [t("Igneous", "Ígnea"), t("Sedimentary", "Sedimentaria"), t("Metamorphic", "Metamórfica")]
    PI = [t("Did it come from melted rock that cooled?", "¿Viene de roca fundida que se enfrió?"), t("Did it form from piled-up, pressed pieces?", "¿Se formó con fragmentos acumulados y compactados?"), t("Was another rock changed by heat and pressure without melting?", "¿Otra roca cambió por calor y presión sin fundirse?")]
    def item(tit, piezas):
        return {"titulo": tit, "intro": t("Sort each rock by how it formed.", "Clasifique cada roca según cómo se formó."), "grupos": G, "etiqueta": t("Type:", "Tipo:"),
                "piezas": [{"t": a, "v": v, "pista": PI[v]} for a, v in piezas], "extra": t("Melt and cool → igneous; pile up and press → sedimentary; heat and squeeze without melting → metamorphic.", "Fundir y enfriar → ígnea; acumular y compactar → sedimentaria; calentar y presionar sin fundir → metamórfica.")}
    return [
        item(t("Set 1", "Grupo 1"), [(t("Basalt, from cooled lava", "Basalto, de lava enfriada"), 0), (t("Sandstone, made of pressed sand grains", "Arenisca, de granos de arena compactados"), 1), (t("Marble, made from limestone under heat and pressure", "Mármol, que procede de caliza sometida a calor y presión"), 2), (t("A rock with a fossil shell in it", "Una roca con una concha fósil"), 1), (t("Granite, with large crystals, cooled deep underground", "Granito, de cristales grandes, enfriado en profundidad"), 0)]),
        item(t("Set 2", "Grupo 2"), [(t("Slate, made from shale squeezed into thin sheets", "Pizarra, de lutita comprimida en láminas"), 2), (t("Limestone, made of shells piled up on a sea floor", "Caliza, de conchas acumuladas en el fondo marino"), 1), (t("Obsidian, a glassy rock from lava that cooled fast", "Obsidiana, roca vítrea de lava enfriada muy rápido"), 0), (t("A rock with bands of squeezed, bent crystals", "Una roca con bandas de cristales aplastados y doblados"), 2), (t("Conglomerate, pebbles cemented together", "Conglomerado, guijarros cementados entre sí"), 1)]),
    ]


def banco_ciclo():
    d = [(t("A sedimentary rock is put under great heat and pressure without melting. It becomes…", "Una roca sedimentaria se somete a mucho calor y presión sin fundirse. Se convierte en roca…"), [t("metamorphic", "metamórfica"), t("igneous", "ígnea"), t("sedimentary again", "sedimentaria otra vez")], 0, t("Heat and squeeze, no melting.", "Calor y presión, sin fundir.")),
         (t("Any rock that melts completely and then cools becomes…", "Cualquier roca que se funde por completo y luego se enfría se convierte en roca…"), [t("igneous", "ígnea"), t("metamorphic", "metamórfica"), t("sedimentary", "sedimentaria")], 0, t("Melt and cool.", "Fundir y enfriar.")),
         (t("Rain and wind wear a granite mountain into sand, which is buried and pressed. The new rock is…", "La lluvia y el viento desgastan una montaña de granito hasta convertirla en arena, que se entierra y compacta. La roca nueva es…"), [t("sedimentary", "sedimentaria"), t("igneous", "ígnea"), t("metamorphic", "metamórfica")], 0, t("Erosion, then pile up and press.", "Erosión y después acumular y compactar.")),
         (t("Where does the rock cycle start?", "¿Dónde empieza el ciclo de las rocas?"), [t("It has no starting point: it is a closed loop", "No tiene punto de partida: es un proceso cerrado"), t("Always with igneous rock", "Siempre con la roca ígnea"), t("Always with sediment", "Siempre con los sedimentos")], 0, t("Any type can become any other.", "Cualquier tipo puede convertirse en otro.")),
         (t("Why don’t igneous rocks have fossils?", "¿Por qué las rocas ígneas no tienen fósiles?"), [t("Everything in them was once melted", "Todo en ellas estuvo fundido"), t("They are too young", "Son demasiado jóvenes"), t("Fossils only form on land", "Los fósiles solo se forman en tierra")], 0, t("Melting destroys any remains.", "La fusión destruye cualquier resto.")),
         (t("What breaks rocks down into sediment?", "¿Qué descompone las rocas en sedimentos?"), [t("Erosion and weathering by water, wind, and ice", "La erosión y la meteorización por agua, viento y hielo"), t("Heat and pressure deep underground", "El calor y la presión en profundidad"), t("Melting", "La fusión")], 0, t("Surface processes make sediment.", "Los procesos de superficie producen sedimentos."))]
    return [{"enun": f"<p>{q}</p>", "ops": o, "ok": k, "pista": t("Melt and cool → igneous; pile up and press → sedimentary; heat and squeeze without melting → metamorphic.", "Fundir y enfriar → ígnea; acumular y compactar → sedimentaria; calentar y presionar sin fundir → metamórfica."), "exp": e} for q, o, k, e in d]


def banco_columnas():
    rnd = random.Random(71)
    out = []
    letras = "ABCDEF"
    for n in range(14):
        k = rnd.choice([4, 5])
        capas = [t(f"Layer {letras[i]}", f"Capa {letras[i]}") for i in range(k)]
        corta = rnd.randint(1, k - 1)
        falla = rnd.choice([None, None, rnd.randint(1, k - 1)])
        if falla == corta:
            falla = None
        svg = columna(capas, corta, falla=falla)
        tipo = n % 4 if falla else n % 3
        nom = lambda i: letras[i]
        if tipo == 0:
            q = t("Which layer is the <strong>oldest</strong>?", "¿Qué capa es la <strong>más antigua</strong>?")
            ops = [capas[0], capas[-1], capas[k // 2], t("You cannot tell", "No se puede saber")]
            ok, e = 0, t(f"Superposition: the bottom layer, {capas[0]}, was laid down first.", f"Superposición: la de abajo, {capas[0]}, se depositó primero.")
        elif tipo == 1:
            q = t("Which layer is the <strong>youngest</strong>?", "¿Qué capa es la <strong>más reciente</strong>?")
            ops = [capas[-1], capas[0], t("The intrusion", "La intrusión"), t("You cannot tell", "No se puede saber")]
            ok, e = 0, t(f"The top layer, {capas[-1]}, covers everything else, so it is the youngest.", f"La capa de arriba, {capas[-1]}, cubre todo lo demás: es la más reciente.")
        elif tipo == 2:
            q = t("When did the <strong>intrusion</strong> form?", "¿Cuándo se formó la <strong>intrusión</strong>?")
            bien = t(f"After layer {nom(corta - 1)} and before layer {nom(corta)}", f"Después de la capa {nom(corta - 1)} y antes de la capa {nom(corta)}")
            ops = [bien, t(f"Before layer {nom(0)}", f"Antes de la capa {nom(0)}"), t(f"After layer {nom(k - 1)}", f"Después de la capa {nom(k - 1)}"),
                   t(f"At the same time as layer {nom(corta)}", f"Al mismo tiempo que la capa {nom(corta)}")]
            ok, e = 0, t(f"It cuts {', '.join(nom(i) for i in range(corta))}, so it is younger than them; layer {nom(corta)} covers it, so it is older than {nom(corta)}.", f"Corta {', '.join(nom(i) for i in range(corta))}, así que es más joven que ellas; la capa {nom(corta)} la cubre, así que es anterior a {nom(corta)}.")
        else:
            q = t("Which happened <strong>first</strong>: the intrusion or the fault?", "¿Qué ocurrió <strong>primero</strong>: la intrusión o la falla?")
            if corta < falla:
                ok, e = 0, t(f"The intrusion is covered by layer {nom(corta)}, but the fault breaks layer {nom(corta)} and more, so the fault came later.", f"La capa {nom(corta)} cubre la intrusión, pero la falla rompe la capa {nom(corta)} y otras más: la falla es posterior.")
            else:
                ok, e = 1, t(f"The fault is covered by layer {nom(falla)}, but the intrusion cuts layer {nom(falla)} and more, so the intrusion came later.", f"La capa {nom(falla)} cubre la falla, pero la intrusión corta la capa {nom(falla)} y otras más: la intrusión es posterior.")
            ops = [t("The intrusion", "La intrusión"), t("The fault", "La falla"), t("Both at the same time", "Las dos a la vez"), t("You cannot tell", "No se puede saber")]
        out.append({"enun": svg + f"<p><strong>{q}</strong></p>", "ops": ops, "ok": ok, "enOrden": True,
                    "pista": t("Lower layers are older. Whatever cuts a layer is younger than it; whatever covers something is younger than it.", "Las capas de abajo son más antiguas. Lo que corta una capa es más joven que ella; lo que cubre algo es más joven que eso."), "exp": e})
    return out


def ordenes_tiempo():
    ev = [(t("Earth forms", "Se forma la Tierra"), "4.6 × 10⁹"), (t("First forms of life", "Primeras formas de vida"), "3.5 × 10⁹"), (t("First animals with shells", "Primeros animales con concha"), "5.4 × 10⁸"),
          (t("First dinosaurs", "Primeros dinosaurios"), "2.3 × 10⁸"), (t("Non-bird dinosaurs die out", "Se extinguen los dinosaurios no aviares"), "6.6 × 10⁷"), (t("First modern humans", "Primeros seres humanos modernos"), "3 × 10⁵")]
    pasos = [f"{a} · {t('about', 'hace unos')} {b} {t('years ago', 'años')}" for a, b in ev]
    cons = {f"{i}>{i - 1}": t(f"{ev[i][1]} years is less time ago than {ev[i - 1][1]}: compare the exponents first.", f"Hace {ev[i][1]} años es más reciente que hace {ev[i - 1][1]}: compare primero los exponentes.") for i in range(1, 6)}
    return [{"titulo": t("Geologic time · From oldest to most recent", "Tiempo geológico · Del más antiguo al más reciente"),
             "intro": t("Order the events from the <strong>oldest</strong> (largest number of years ago) to the <strong>most recent</strong> with ▲ and ▼.", "Ordene los sucesos del <strong>más antiguo</strong> (más años atrás) al <strong>más reciente</strong> con ▲ y ▼."),
             "pasos": pasos, "inicio": [3, 5, 0, 4, 1, 2], "cons": cons,
             "general": t("A larger exponent means longer ago; with equal exponents, compare the front numbers.", "Un exponente mayor significa más tiempo atrás; con exponentes iguales, se comparan los números de delante.")}]


